import { DiagramEditSessionService } from './diagram_edit_session_service'
import type { DiagramRecord } from './diagram_index'
import { DiagramSelectionService, type DiagramSelectionIdentity } from './diagram_selection_service'
import type { DiagramViewSourceSnapshot } from './diagram_view_service'

const diagram: DiagramData = {
    edges: [{ from: 'orders', id: 'orders-store', kind: 'connection', to: 'store' }],
    groups: [{ id: 'backend', label: 'Backend', nodeIds: ['orders', 'store'] }],
    meta: { description: 'Orders architecture', title: 'Overview', type: 'architecture', version: 1 },
    nodes: [
        { id: 'orders', label: 'Orders', role: 'focal' },
        { id: 'store', label: 'Store', role: 'store' },
    ],
}
const record: DiagramRecord = { actionId: 'overview', id: 'diagram-1', label: 'Overview', path: 'design/diagrams/overview.json' }
const project = { branch: 'main', id: 'project', rootPath: 'C:/repo' }
const orders: DiagramSelectionIdentity = { objectId: 'orders', objectKind: 'node' }
const store: DiagramSelectionIdentity = { objectId: 'store', objectKind: 'node' }
const edge: DiagramSelectionIdentity = { objectId: 'orders-store', objectKind: 'edge' }
const group: DiagramSelectionIdentity = { objectId: 'backend', objectKind: 'group' }

class DiagramSourceStub extends EventTarget {
    private source: DiagramViewSourceSnapshot | null = { diagram, record }

    getSourceSnapshot = () => this.source

    subscribeSource = (listener: () => void) => {
        this.addEventListener('sourceChanged', listener)

        return () => this.removeEventListener('sourceChanged', listener)
    }
}

function createHarness() {
    const session = new DiagramEditSessionService(new DiagramSourceStub())
    const selection = new DiagramSelectionService(session)
    session.bindProject(project)
    session.start()

    return { selection, session }
}

describe('DiagramSelectionService', () => {
    it('replaces, adds, removes, toggles, clears, and queries mixed object identities', () => {
        const { selection, session } = createHarness()
        const editableDiagram = session.getEditableDiagram()
        const ordersNode = session.getNodeSnapshot('orders')

        expect(selection.replace([orders])).toBe(true)
        expect(selection.isSelected(orders)).toBe(true)
        expect(selection.add(edge)).toBe(true)
        expect(selection.add(edge)).toBe(false)
        expect(selection.getSelectionSnapshot()).toEqual([orders, edge])

        expect(selection.remove(orders)).toBe(true)
        expect(selection.remove(orders)).toBe(false)
        expect(selection.toggle(group)).toBe(true)
        expect(selection.toggle(edge)).toBe(true)
        expect(selection.getSelectionSnapshot()).toEqual([group])
        expect(selection.getSelectedSnapshot(group)).toBe(true)

        expect(selection.clear()).toBe(true)
        expect(selection.clear()).toBe(false)
        expect(selection.getSelectionSnapshot()).toEqual([])
        expect(session.getEditableDiagram()).toBe(editableDiagram)
        expect(session.getNodeSnapshot('orders')).toBe(ordersNode)
    })

    it('keeps snapshots stable for no-ops and publishes only changed identity scopes', () => {
        const { selection } = createHarness()
        selection.replace([orders, edge])
        const snapshot = selection.getSelectionSnapshot()
        const ordersChangedOne = vi.fn()
        const ordersChangedTwo = vi.fn()
        const storeChanged = vi.fn()
        const edgeChanged = vi.fn()
        const membershipChanged = vi.fn()
        selection.subscribeSelected(orders, ordersChangedOne)
        selection.subscribeSelected(orders, ordersChangedTwo)
        selection.subscribeSelected(store, storeChanged)
        selection.subscribeSelected(edge, edgeChanged)
        selection.subscribeSelection(membershipChanged)

        expect(selection.replace([edge, orders, orders])).toBe(false)
        expect(selection.getSelectionSnapshot()).toBe(snapshot)
        expect(membershipChanged).not.toHaveBeenCalled()

        expect(selection.replace([store, edge])).toBe(true)
        expect(ordersChangedOne).toHaveBeenCalledOnce()
        expect(ordersChangedTwo).toHaveBeenCalledOnce()
        expect(storeChanged).toHaveBeenCalledOnce()
        expect(edgeChanged).not.toHaveBeenCalled()
        expect(membershipChanged).toHaveBeenCalledOnce()
    })

    it('rejects missing identities and selection without an active edit session', () => {
        const session = new DiagramEditSessionService(new DiagramSourceStub())
        const selection = new DiagramSelectionService(session)

        expect(() => selection.add(orders)).toThrow('without an active edit session')
        session.bindProject(project)
        session.start()
        expect(() => selection.add({ objectId: 'missing', objectKind: 'node' })).toThrow(
            'Diagram node missing does not exist',
        )
        expect(selection.getSelectionSnapshot()).toEqual([])
    })

    it('clears selection when the edit session restarts or ends', () => {
        const { selection, session } = createHarness()
        const membershipChanged = vi.fn()
        selection.subscribeSelection(membershipChanged)
        selection.replace([orders, edge])
        membershipChanged.mockClear()

        session.start()
        expect(selection.getSelectionSnapshot()).toEqual([])
        expect(membershipChanged).toHaveBeenCalledOnce()

        selection.add(group)
        membershipChanged.mockClear()
        session.discard()
        expect(selection.getSelectionSnapshot()).toEqual([])
        expect(membershipChanged).toHaveBeenCalledOnce()
    })

    it('prunes deleted and cascaded identities before collection membership publication', () => {
        const { selection, session } = createHarness()
        selection.replace([orders, edge, group])
        const selectionDuringNodePublication: DiagramSelectionIdentity[][] = []
        const selectionDuringEdgePublication: DiagramSelectionIdentity[][] = []
        const selectionDuringGroupPublication: DiagramSelectionIdentity[][] = []
        session.subscribeCollectionMembership('node', () => {
            selectionDuringNodePublication.push([...selection.getSelectionSnapshot()])
        })
        session.subscribeCollectionMembership('edge', () => {
            selectionDuringEdgePublication.push([...selection.getSelectionSnapshot()])
        })
        session.subscribeCollectionMembership('group', () => {
            selectionDuringGroupPublication.push([...selection.getSelectionSnapshot()])
        })

        expect(session.removeNode('orders')).toBe(true)
        expect(selectionDuringNodePublication).toEqual([[group]])
        expect(selectionDuringEdgePublication).toEqual([[group]])
        expect(selection.getSelectionSnapshot()).toEqual([group])

        expect(session.removeGroup('backend')).toBe(true)
        expect(selectionDuringGroupPublication).toEqual([[]])
        expect(selection.getSelectionSnapshot()).toEqual([])
    })
})

import { ThemeProvider } from '@mui/material'
import { cleanup, fireEvent, render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { afterEach, describe, expect, it, vi } from 'vitest'
import type { DiagramFlowPreset, DiagramType } from '../../services/diagrams/diagram_data'
import type { PositionedDiagramNode } from '../../services/diagrams/diagram_layout'
import { createAppTheme } from '../../theme/app_theme'
import { DiagramNode } from './diagram_node'

function positioned(overrides: Partial<PositionedDiagramNode> = {}): PositionedDiagramNode {
    // Cast: exactOptionalPropertyTypes rejects spreading a Partial whose optional members may be explicitly undefined.
    return { fanIn: 0, height: 72, id: 'one', label: 'One', width: 160, x: 0, y: 0, ...overrides } as PositionedDiagramNode
}

function renderNode(node: PositionedDiagramNode, diagramType: DiagramType = 'architecture', flowPreset?: DiagramFlowPreset) {
    const onSelect = vi.fn()
    render(
        <ThemeProvider theme={createAppTheme('dark')}>
            <DiagramNode diagramType={diagramType} flowPreset={flowPreset} node={node} onSelect={onSelect} />
        </ThemeProvider>,
    )

    return { button: screen.getByRole('button', { name: node.label }), onSelect }
}

function scrollWrapper(button: HTMLElement) {
    return button.querySelector('[data-diagram-scroll="content"]') as HTMLElement | null
}

describe('DiagramNode', () => {
    afterEach(cleanup)

    it('puts tag, label and sublabel in a scrollable wrapper that only anchors to the top when content overflows', () => {
        const { button } = renderNode(positioned({ sublabel: 'a very long sublabel that does not fit', tag: 'service' }))
        const wrapper = scrollWrapper(button)

        expect(wrapper).not.toBeNull()
        expect(getComputedStyle(wrapper as HTMLElement).overflowY).toBe('auto')
        expect(getComputedStyle(wrapper as HTMLElement).justifyContent).toBe('safe center')
        expect(getComputedStyle(wrapper as HTMLElement).minHeight).toBe('0px')
        expect(wrapper).toContainElement(screen.getByText('service'))
        expect(wrapper).toContainElement(screen.getByText('One'))
        expect(wrapper).toContainElement(screen.getByText('a very long sublabel that does not fit'))
    })

    it('wraps a single unbroken token in the label and sublabel instead of clipping it', () => {
        renderNode(positioned({ label: 'src/services/diagrams/diagram_layout.ts', sublabel: 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa' }))

        expect(getComputedStyle(screen.getByText('src/services/diagrams/diagram_layout.ts')).overflowWrap).toBe('anywhere')
        expect(getComputedStyle(screen.getByText('aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa')).overflowWrap).toBe('anywhere')
    })

    it('keeps the fanIn badge outside the scroll wrapper so it does not scroll away', () => {
        const { button } = renderNode(positioned({ fanIn: 3 }), 'dependency')

        expect(scrollWrapper(button)).not.toContainElement(screen.getByText('3 in'))
        expect(button).toContainElement(screen.getByText('3 in'))
    })

    it('keeps the entity divider and field list inside the same scroll wrapper as the header', () => {
        const node = positioned({ fields: [{ key: 'primary' as const, name: 'id', type: 'UUID' }], height: 120 })
        const { button } = renderNode(node, 'entity')
        const fields = screen.getByText('# id: UUID').parentElement as HTMLElement

        expect(scrollWrapper(button)).toContainElement(fields)
        expect(getComputedStyle(fields).borderTop).toContain('1px solid')
    })

    it('renders no text and no scroll wrapper for state preset start and end markers', () => {
        const { button } = renderNode(positioned({ height: 24, kind: 'start', label: 'Start', width: 24 }), 'flow', 'state')

        expect(scrollWrapper(button)).toBeNull()
        expect(button).toBeEmptyDOMElement()
    })

    it('honours an explicit height from the diagram JSON', () => {
        const { button } = renderNode(positioned({ height: 200 }))

        expect(getComputedStyle(button).height).toBe('200px')
    })

    it('selects the node on a plain click and on Enter', async () => {
        const { button, onSelect } = renderNode(positioned())
        const user = userEvent.setup()

        await user.click(button)
        expect(onSelect).toHaveBeenCalledWith(expect.objectContaining({ id: 'one', label: 'One' }))

        onSelect.mockClear()
        button.focus()
        await user.keyboard('{Enter}')
        expect(onSelect).toHaveBeenCalledWith(expect.objectContaining({ id: 'one', label: 'One' }))
    })

    it('does not select the node when the content scrolled between mousedown and click', () => {
        const { button, onSelect } = renderNode(positioned({ sublabel: 'long enough to scroll' }))
        const wrapper = scrollWrapper(button) as HTMLElement

        fireEvent.mouseDown(button)
        wrapper.scrollTop = 24
        fireEvent.click(button)

        expect(onSelect).not.toHaveBeenCalled()
    })

    it('keeps non-drilldown node content scrollable without allowing selection', async () => {
        const { button, onSelect } = renderNode(positioned({ drilldown: false, sublabel: 'long enough to scroll' }))
        const wrapper = scrollWrapper(button) as HTMLElement
        const user = userEvent.setup()

        expect(button).toHaveAttribute('aria-disabled', 'true')
        expect(button).toHaveAttribute('tabindex', '-1')
        expect(button).not.toBeDisabled()
        expect(getComputedStyle(wrapper).overflowY).toBe('auto')

        await user.click(wrapper)
        fireEvent.keyDown(button, { key: 'Enter' })

        expect(onSelect).not.toHaveBeenCalled()
    })
})

import type { Theme } from '@mui/material'
import type { DiagramEdgeKind } from '../../services/diagrams/diagram_data'

const DEFAULT_EDGE_STROKE_WIDTH = 1.2
const ACCENT_EDGE_STROKE_WIDTH = 1.5
const FOCUSED_EDGE_STROKE_WIDTH = 3

export interface DiagramEdgeVisualStyle {
    arrowhead: 'filled' | 'open'
    color: string
    strokeDasharray?: string
    strokeWidth: number
}

/** Resolves shared connection appearance for diagram edges and legend samples. */
export function diagramEdgeStyle(kind: DiagramEdgeKind, theme: Theme, focused = false): DiagramEdgeVisualStyle {
    const accent = kind === 'cycle' || kind === 'success'

    return {
        arrowhead: kind === 'async' ? 'open' : 'filled',
        color: focused || accent ? theme.palette.primary.main : theme.palette.text.secondary,
        ...(['async', 'cycle', 'return'].includes(kind) ? { strokeDasharray: '4 3' } : {}),
        strokeWidth: focused ? FOCUSED_EDGE_STROKE_WIDTH : accent ? ACCENT_EDGE_STROKE_WIDTH : DEFAULT_EDGE_STROKE_WIDTH,
    }
}

import { memo } from 'react'
import type { DiagramWaypoint } from '../../services/diagrams/diagram_data'
import {
    diagramEditSessionService, type DiagramEditSessionService,
} from '../../services/diagrams/diagram_edit_session_service'
import { diagramGeometryService, type DiagramGeometryService } from '../../services/diagrams/diagram_geometry_service'
import type { PositionedDiagramEdge } from '../../services/diagrams/diagram_layout'
import { DiagramEdge } from './diagram_edge'
import type { DiagramSelectHandler } from './diagram_selection'
import { useDiagramEdgeLabelPlacement, useDiagramEdgeRoute } from './use_diagram_geometry'
import { useEditableDiagramEdgeField } from './use_editable_diagram'

const EMPTY_NODE_LABELS: ReadonlyMap<string, string> = new Map()

interface EditableDiagramEdgeProps {
    edgeId: string
    geometry?: DiagramGeometryService
    onSelect: DiagramSelectHandler
    session?: DiagramEditSessionService
}

/**
 * One connection of the New diagram. It observes its own model fields and its own derived route.
 */
function EditableDiagramEdgeLeaf({
    edgeId,
    geometry = diagramGeometryService,
    onSelect,
    session = diagramEditSessionService,
}: EditableDiagramEdgeProps) {
    const from = useEditableDiagramEdgeField(edgeId, 'from', session)
    const fromCardinality = useEditableDiagramEdgeField(edgeId, 'fromCardinality', session)
    const kind = useEditableDiagramEdgeField(edgeId, 'kind', session)
    const label = useEditableDiagramEdgeField(edgeId, 'label', session)
    const to = useEditableDiagramEdgeField(edgeId, 'to', session)
    const toCardinality = useEditableDiagramEdgeField(edgeId, 'toCardinality', session)
    const labelPlacement = useDiagramEdgeLabelPlacement(edgeId, geometry)
    const points = useDiagramEdgeRoute(edgeId, geometry)
    if (from === null || to === null || kind === null || points.length === 0) return null

    const edge: PositionedDiagramEdge = {
        from,
        id: edgeId,
        kind,
        points: points as DiagramWaypoint[],
        to,
        ...(fromCardinality ? { fromCardinality } : {}),
        ...(label ? { label } : {}),
        ...(labelPlacement ? { labelPlacement } : {}),
        ...(toCardinality ? { toCardinality } : {}),
    }

    return <DiagramEdge edge={edge} nodeLabels={EMPTY_NODE_LABELS} onSelect={onSelect} />
}

/** Memoised so a collection host rerender caused by another member cannot rerender this leaf. */
export const EditableDiagramEdge = memo(EditableDiagramEdgeLeaf)

import { memo } from 'react'
import type { DiagramEntityField } from '../../services/diagrams/diagram_data'
import {
    diagramEditSessionService, type DiagramEditSessionService,
} from '../../services/diagrams/diagram_edit_session_service'
import { diagramGeometryService, type DiagramGeometryService } from '../../services/diagrams/diagram_geometry_service'
import type { PositionedDiagramNode } from '../../services/diagrams/diagram_layout'
import { DiagramNode } from './diagram_node'
import type { DiagramSelectHandler } from './diagram_selection'
import { useDiagramNodeGeometryField } from './use_diagram_geometry'
import { useEditableDiagramMetadataField, useEditableDiagramNodeField } from './use_editable_diagram'

interface EditableDiagramNodeProps {
    geometry?: DiagramGeometryService
    nodeId: string
    onSelect: DiagramSelectHandler
    session?: DiagramEditSessionService
}

/**
 * One node of the New diagram. Every value it renders arrives through its own field subscription, so an edit to a
 * sibling node, an edge, a group, or the metadata cannot rerender this leaf.
 */
function EditableDiagramNodeLeaf({
    geometry = diagramGeometryService,
    nodeId,
    onSelect,
    session = diagramEditSessionService,
}: EditableDiagramNodeProps) {
    const diagramType = useEditableDiagramMetadataField('type', session)
    const preset = useEditableDiagramMetadataField('preset', session)
    const drilldown = useEditableDiagramNodeField(nodeId, 'drilldown', session)
    const fields = useEditableDiagramNodeField(nodeId, 'fields', session)
    const kind = useEditableDiagramNodeField(nodeId, 'kind', session)
    const label = useEditableDiagramNodeField(nodeId, 'label', session)
    const role = useEditableDiagramNodeField(nodeId, 'role', session)
    const sublabel = useEditableDiagramNodeField(nodeId, 'sublabel', session)
    const tag = useEditableDiagramNodeField(nodeId, 'tag', session)
    const fanIn = useDiagramNodeGeometryField(nodeId, 'fanIn', geometry)
    const height = useDiagramNodeGeometryField(nodeId, 'height', geometry)
    const width = useDiagramNodeGeometryField(nodeId, 'width', geometry)
    const x = useDiagramNodeGeometryField(nodeId, 'x', geometry)
    const y = useDiagramNodeGeometryField(nodeId, 'y', geometry)
    if (!diagramType || label === null || role === null || width === null || height === null) return null

    const node: PositionedDiagramNode = {
        fanIn: fanIn ?? 0,
        height,
        id: nodeId,
        label,
        role,
        width,
        x: x ?? 0,
        y: y ?? 0,
        ...(drilldown === undefined || drilldown === null ? {} : { drilldown }),
        ...(fields ? { fields: fields as DiagramEntityField[] } : {}),
        ...(kind ? { kind } : {}),
        ...(sublabel ? { sublabel } : {}),
        ...(tag ? { tag } : {}),
    }

    return (
        <DiagramNode
            diagramType={diagramType}
            flowPreset={preset ?? undefined}
            node={node}
            onSelect={onSelect}
        />
    )
}

/** Memoised so a collection host rerender caused by another member cannot rerender this leaf. */
export const EditableDiagramNode = memo(EditableDiagramNodeLeaf)

import { memo } from 'react'
import {
    diagramEditSessionService, type DiagramEditSessionService,
} from '../../services/diagrams/diagram_edit_session_service'
import { diagramGeometryService, type DiagramGeometryService } from '../../services/diagrams/diagram_geometry_service'
import type { PositionedDiagramGroup } from '../../services/diagrams/diagram_layout'
import { DiagramGroup } from './diagram_group'
import { useDiagramGroupGeometryField } from './use_diagram_geometry'
import { useEditableDiagramGroupField } from './use_editable_diagram'

interface EditableDiagramGroupProps {
    geometry?: DiagramGeometryService
    groupId: string
    session?: DiagramEditSessionService
}

/** One containment box of the New diagram, bound to its own label and its own derived box. */
function EditableDiagramGroupLeaf({
    geometry = diagramGeometryService,
    groupId,
    session = diagramEditSessionService,
}: EditableDiagramGroupProps) {
    const label = useEditableDiagramGroupField(groupId, 'label', session)
    const height = useDiagramGroupGeometryField(groupId, 'height', geometry)
    const width = useDiagramGroupGeometryField(groupId, 'width', geometry)
    const x = useDiagramGroupGeometryField(groupId, 'x', geometry)
    const y = useDiagramGroupGeometryField(groupId, 'y', geometry)
    if (label === null || height === null || width === null) return null

    // Membership is edited elsewhere and is not rendered by the box, so this view object carries no member IDs.
    const group: PositionedDiagramGroup = { height, id: groupId, label, nodeIds: [], width, x: x ?? 0, y: y ?? 0 }

    return <DiagramGroup group={group} />
}

/** Memoised so a collection host rerender caused by another member cannot rerender this leaf. */
export const EditableDiagramGroup = memo(EditableDiagramGroupLeaf)

import { createTheme, type PaletteMode, type Theme } from '@mui/material'
import { DEFAULT_COLOR_SCHEME, type ColorSchemeConfig } from './theme_config'
import type { ProjectBackgroundShade } from './project_background_shade'

const APP_BORDER_RADIUS = 8

const LIGHT_PROJECT_BACKGROUNDS: Record<ProjectBackgroundShade, { default: string; paper: string }> = {
    amber: { default: '#faf7ef', paper: '#fffefa' },
    blue: { default: '#f1f5fa', paper: '#fbfdff' },
    green: { default: '#f1f7f3', paper: '#fbfefc' },
    neutral: { default: '#f4f6f8', paper: '#ffffff' },
    purple: { default: '#f7f3fa', paper: '#fefcff' },
    red: { default: '#faf3f3', paper: '#fffdfd' },
}

const DARK_PROJECT_BACKGROUNDS: Record<ProjectBackgroundShade, { default: string; paper: string }> = {
    amber: { default: '#1b1812', paper: '#242016' },
    blue: { default: '#101821', paper: '#19232e' },
    green: { default: '#111a17', paper: '#1a2521' },
    neutral: { default: '#10151c', paper: '#1a212b' },
    purple: { default: '#19151d', paper: '#231d29' },
    red: { default: '#1b1416', paper: '#261d20' },
}

const LIGHT_PALETTE = {
    divider: '#e3e8ef',
    text: { disabled: '#9aa4b2', primary: '#1c2536', secondary: '#4b5565' },
}

const DARK_PALETTE = {
    divider: '#2a3441',
    text: { disabled: '#697586', primary: '#e6eaf0', secondary: '#9aa4b2' },
}

function paletteForMode(mode: PaletteMode, colorScheme: ColorSchemeConfig, backgroundShade: ProjectBackgroundShade) {
    const isDark = mode === 'dark'
    const modePalette = isDark ? DARK_PALETTE : LIGHT_PALETTE
    const background = isDark ? DARK_PROJECT_BACKGROUNDS[backgroundShade] : LIGHT_PROJECT_BACKGROUNDS[backgroundShade]
    const track = isDark ? '#151c25' : '#eceff3'
    const primaryBackground = isDark ? '#202a36' : '#f0f3f7'

    return {
        ...modePalette,
        background,
        action: {
            hover: track,
            selected: primaryBackground,
        },
        custom: {
            borderHover: modePalette.text.disabled,
            borderStrong: modePalette.divider,
            chartPalette: isDark
                ? ['#7aa2f7', '#9ece6a', '#e0af68', '#bb9af7', '#7dcfff', '#f7768e', '#73daca', '#c0caf5']
                : ['#3366cc', '#2e8b57', '#d97706', '#7c3aed', '#0284c7', '#dc2626', '#0f766e', '#64748b'],
            chartPalettes: isDark
                ? {
                    claude: ['#e0af68', '#f7768e', '#bb9af7', '#c0caf5'],
                    codex: ['#7aa2f7', '#9ece6a', '#7dcfff', '#73daca'],
                }
                : {
                    claude: ['#d97706', '#dc2626', '#7c3aed', '#64748b'],
                    codex: ['#3366cc', '#2e8b57', '#0284c7', '#0f766e'],
                },
            colHead: modePalette.text.secondary,
            primaryBg: primaryBackground,
            text3: modePalette.text.secondary,
            text4: modePalette.text.disabled,
            track,
        },
        info: { main: isDark ? '#4fc3f7' : '#29a8e0' },
        mode,
        primary: {
            contrastText: isDark ? '#0d1420' : '#ffffff',
            dark: colorScheme.primary.dark,
            light: colorScheme.primary.light,
            main: isDark ? colorScheme.primary.light : colorScheme.primary.regular,
        },
        secondary: {
            dark: colorScheme.secondary.dark,
            light: colorScheme.secondary.light,
            main: isDark ? colorScheme.secondary.light : colorScheme.secondary.regular,
        },
        success: { main: isDark ? '#43a047' : '#2e7d32' },
        warning: { dark: '#ed6c02', main: '#f9a825' },
    }
}

/** Build the complete shared MUI theme for the selected palette mode. */
export function createAppTheme(
    mode: PaletteMode,
    colorScheme: ColorSchemeConfig = DEFAULT_COLOR_SCHEME,
    backgroundShade: ProjectBackgroundShade = 'neutral',
): Theme {
    const isDark = mode === 'dark'

    return createTheme({
        palette: paletteForMode(mode, colorScheme, backgroundShade),
        shape: { borderRadius: APP_BORDER_RADIUS },
        typography: {
            button: { fontWeight: 600, textTransform: 'none' },
            fontFamily: 'Inter, "Segoe UI", Roboto, sans-serif',
            fontSize: 13,
        },
        components: {
            MuiAppBar: { defaultProps: { elevation: 0 } },
            MuiButton: {
                defaultProps: { disableElevation: true },
                styleOverrides: { root: { borderRadius: APP_BORDER_RADIUS } },
            },
            MuiCssBaseline: {
                styleOverrides: {
                    ':root': {
                        '--md2-card-drag-shadow': isDark ? '0 0 0 1px #455263' : '0 12px 24px rgba(16,24,40,0.18)',
                        '--md2-card-hover-shadow': isDark ? 'none' : '0 4px 12px rgba(16,24,40,0.12)',
                        '--md2-card-shadow': isDark ? 'none' : '0 1px 2px rgba(16,24,40,0.05)',
                    },
                },
            },
            MuiIconButton: { styleOverrides: { root: { borderRadius: APP_BORDER_RADIUS } } },
            MuiMenuItem: { defaultProps: { dense: true } },
            MuiInput: {
                styleOverrides: {
                    root: {
                        '&:before': { borderBottom: '1px solid transparent' },
                        '&:hover:not(.Mui-disabled, .Mui-error):before': { borderBottomColor: 'currentColor' },
                    },
                },
            },
            MuiPaper: { defaultProps: { elevation: 0 }, styleOverrides: { root: { backgroundImage: 'none' } } },
            MuiTextField: { defaultProps: { variant: 'standard' } },
            MuiTooltip: { defaultProps: { arrow: true } },
        },
    })
}

import { describe, expect, it, vi } from 'vitest'
import type { DiagramData } from './diagram_data'
import { DiagramEditSessionService } from './diagram_edit_session_service'
import type { DiagramRecord } from './diagram_index'
import { DiagramSelectionService, type DiagramSelectionIdentity } from './diagram_selection_service'
import type { DiagramViewSourceSnapshot } from './diagram_view_service'

const diagram: DiagramData = {
    edges: [{ from: 'orders', id: 'orders-store', kind: 'connection', to: 'store' }],
    groups: [{ id: 'backend', label: 'Backend', nodeIds: ['orders', 'store'] }],
    meta: { description: 'Orders architecture', title: 'Overview', type: 'architecture', version: 1 },
    nodes: [
        { id: 'orders', label: 'Orders', role: 'focal' },
        { id: 'store', label: 'Store', role: 'store' },
    ],
}
const record: DiagramRecord = { actionId: 'overview', id: 'diagram-1', label: 'Overview', path: 'design/diagrams/overview.json' }
const project = { branch: 'main', id: 'project', rootPath: 'C:/repo' }
const orders: DiagramSelectionIdentity = { objectId: 'orders', objectKind: 'node' }
const store: DiagramSelectionIdentity = { objectId: 'store', objectKind: 'node' }
const edge: DiagramSelectionIdentity = { objectId: 'orders-store', objectKind: 'edge' }
const group: DiagramSelectionIdentity = { objectId: 'backend', objectKind: 'group' }

class DiagramSourceStub extends EventTarget {
    private source: DiagramViewSourceSnapshot | null = { diagram, record }

    getSourceSnapshot = () => this.source

    subscribeSource = (listener: () => void) => {
        this.addEventListener('sourceChanged', listener)

        return () => this.removeEventListener('sourceChanged', listener)
    }
}

function createHarness() {
    const session = new DiagramEditSessionService(new DiagramSourceStub())
    const selection = new DiagramSelectionService(session)
    session.bindProject(project)
    session.start()

    return { selection, session }
}

describe('DiagramSelectionService', () => {
    it('replaces, adds, removes, toggles, clears, and queries mixed object identities', () => {
        const { selection, session } = createHarness()
        const editableDiagram = session.getEditableDiagram()
        const ordersNode = session.getNodeSnapshot('orders')

        expect(selection.replace([orders])).toBe(true)
        expect(selection.isSelected(orders)).toBe(true)
        expect(selection.add(edge)).toBe(true)
        expect(selection.add(edge)).toBe(false)
        expect(selection.getSelectionSnapshot()).toEqual([orders, edge])

        expect(selection.remove(orders)).toBe(true)
        expect(selection.remove(orders)).toBe(false)
        expect(selection.toggle(group)).toBe(true)
        expect(selection.toggle(edge)).toBe(true)
        expect(selection.getSelectionSnapshot()).toEqual([group])
        expect(selection.getSelectedSnapshot(group)).toBe(true)

        expect(selection.clear()).toBe(true)
        expect(selection.clear()).toBe(false)
        expect(selection.getSelectionSnapshot()).toEqual([])
        expect(session.getEditableDiagram()).toBe(editableDiagram)
        expect(session.getNodeSnapshot('orders')).toBe(ordersNode)
    })

    it('keeps snapshots stable for no-ops and publishes only changed identity scopes', () => {
        const { selection } = createHarness()
        selection.replace([orders, edge])
        const snapshot = selection.getSelectionSnapshot()
        const ordersChangedOne = vi.fn()
        const ordersChangedTwo = vi.fn()
        const storeChanged = vi.fn()
        const edgeChanged = vi.fn()
        const membershipChanged = vi.fn()
        selection.subscribeSelected(orders, ordersChangedOne)
        selection.subscribeSelected(orders, ordersChangedTwo)
        selection.subscribeSelected(store, storeChanged)
        selection.subscribeSelected(edge, edgeChanged)
        selection.subscribeSelection(membershipChanged)

        expect(selection.replace([edge, orders, orders])).toBe(false)
        expect(selection.getSelectionSnapshot()).toBe(snapshot)
        expect(membershipChanged).not.toHaveBeenCalled()

        expect(selection.replace([store, edge])).toBe(true)
        expect(ordersChangedOne).toHaveBeenCalledOnce()
        expect(ordersChangedTwo).toHaveBeenCalledOnce()
        expect(storeChanged).toHaveBeenCalledOnce()
        expect(edgeChanged).not.toHaveBeenCalled()
        expect(membershipChanged).toHaveBeenCalledOnce()
    })

    it('rejects missing identities and selection without an active edit session', () => {
        const session = new DiagramEditSessionService(new DiagramSourceStub())
        const selection = new DiagramSelectionService(session)

        expect(() => selection.add(orders)).toThrow('without an active edit session')
        session.bindProject(project)
        session.start()
        expect(() => selection.add({ objectId: 'missing', objectKind: 'node' })).toThrow(
            'Diagram node missing does not exist',
        )
        expect(selection.getSelectionSnapshot()).toEqual([])
    })

    it('clears selection when the edit session restarts or ends', () => {
        const { selection, session } = createHarness()
        const membershipChanged = vi.fn()
        selection.subscribeSelection(membershipChanged)
        selection.replace([orders, edge])
        membershipChanged.mockClear()

        session.start()
        expect(selection.getSelectionSnapshot()).toEqual([])
        expect(membershipChanged).toHaveBeenCalledOnce()

        selection.add(group)
        membershipChanged.mockClear()
        session.discard()
        expect(selection.getSelectionSnapshot()).toEqual([])
        expect(membershipChanged).toHaveBeenCalledOnce()
    })

    it('prunes deleted and cascaded identities before collection membership publication', () => {
        const { selection, session } = createHarness()
        selection.replace([orders, edge, group])
        const selectionDuringNodePublication: DiagramSelectionIdentity[][] = []
        const selectionDuringEdgePublication: DiagramSelectionIdentity[][] = []
        const selectionDuringGroupPublication: DiagramSelectionIdentity[][] = []
        session.subscribeCollectionMembership('node', () => {
            selectionDuringNodePublication.push([...selection.getSelectionSnapshot()])
        })
        session.subscribeCollectionMembership('edge', () => {
            selectionDuringEdgePublication.push([...selection.getSelectionSnapshot()])
        })
        session.subscribeCollectionMembership('group', () => {
            selectionDuringGroupPublication.push([...selection.getSelectionSnapshot()])
        })

        expect(session.removeNode('orders')).toBe(true)
        expect(selectionDuringNodePublication).toEqual([[group]])
        expect(selectionDuringEdgePublication).toEqual([[group]])
        expect(selection.getSelectionSnapshot()).toEqual([group])

        expect(session.removeGroup('backend')).toBe(true)
        expect(selectionDuringGroupPublication).toEqual([[]])
        expect(selection.getSelectionSnapshot()).toEqual([])
    })
})

import { register } from '../service_injector'
import {
    diagramEditSessionService,
    type DiagramCollectionKind,
    type DiagramEditSessionService,
    type DiagramMembershipChangeDetail,
} from './diagram_edit_session_service'

const SELECTION_MEMBERSHIP_CHANGED_EVENT = 'selection:membership'
const EMPTY_SELECTION: readonly DiagramSelectionIdentity[] = Object.freeze([])

export type DiagramSelectableObjectKind = Extract<DiagramCollectionKind, 'edge' | 'group' | 'node'>

export interface DiagramSelectionIdentity {
    objectId: string
    objectKind: DiagramSelectableObjectKind
}

type DiagramSelectionSession = Pick<
    DiagramEditSessionService,
    | 'getEdgeSnapshot'
    | 'getGroupSnapshot'
    | 'getNodeSnapshot'
    | 'getSessionSnapshot'
    | 'subscribeCollectionMembershipWillChange'
    | 'subscribeSession'
>

function selectionKey({ objectId, objectKind }: DiagramSelectionIdentity) {
    return `${objectKind}:${objectId}`
}

function selectedChangedEvent(identity: DiagramSelectionIdentity) {
    return `selection:${identity.objectKind}:${encodeURIComponent(identity.objectId)}`
}

function frozenIdentity(identity: DiagramSelectionIdentity): DiagramSelectionIdentity {
    return Object.freeze({ objectId: identity.objectId, objectKind: identity.objectKind })
}

/** Owns selected node, edge, and group identities for the active diagram edit session. */
export class DiagramSelectionService extends EventTarget {
    private selection: readonly DiagramSelectionIdentity[] = EMPTY_SELECTION
    private selectedKeys = new Set<string>()
    private readonly session: DiagramSelectionSession

    constructor(session: DiagramSelectionSession = diagramEditSessionService) {
        super()
        this.session = session
        this.session.subscribeSession(this.handleSessionChange)
        this.session.subscribeCollectionMembershipWillChange('edge', this.handleCollectionMembershipWillChange)
        this.session.subscribeCollectionMembershipWillChange('group', this.handleCollectionMembershipWillChange)
        this.session.subscribeCollectionMembershipWillChange('node', this.handleCollectionMembershipWillChange)
    }

    getSelectionSnapshot = () => this.selection

    getSelectedSnapshot = (identity: DiagramSelectionIdentity) => this.isSelected(identity)

    isSelected(identity: DiagramSelectionIdentity) {
        return this.selectedKeys.has(selectionKey(identity))
    }

    subscribeSelection = (listener: () => void) => this.subscribe(SELECTION_MEMBERSHIP_CHANGED_EVENT, listener)

    subscribeSelected = (identity: DiagramSelectionIdentity, listener: () => void) => (
        this.subscribe(selectedChangedEvent(identity), listener)
    )

    replace(identities: readonly DiagramSelectionIdentity[]) {
        const nextSelection: DiagramSelectionIdentity[] = []
        const nextKeys = new Set<string>()
        for (const identity of identities) {
            this.requireSelectableIdentity(identity)
            const key = selectionKey(identity)
            if (nextKeys.has(key)) continue

            nextKeys.add(key)
            nextSelection.push(frozenIdentity(identity))
        }
        if (this.hasSameMembership(nextKeys)) return false

        const changedIdentities = [
            ...this.selection.filter((identity) => !nextKeys.has(selectionKey(identity))),
            ...nextSelection.filter((identity) => !this.selectedKeys.has(selectionKey(identity))),
        ]
        this.selection = nextSelection.length > 0 ? Object.freeze(nextSelection) : EMPTY_SELECTION
        this.selectedKeys = nextKeys
        this.publish(changedIdentities)

        return true
    }

    add(identity: DiagramSelectionIdentity) {
        this.requireSelectableIdentity(identity)
        const key = selectionKey(identity)
        if (this.selectedKeys.has(key)) return false

        const storedIdentity = frozenIdentity(identity)
        this.selectedKeys.add(key)
        this.selection = Object.freeze([...this.selection, storedIdentity])
        this.publish([storedIdentity])

        return true
    }

    remove(identity: DiagramSelectionIdentity) {
        const key = selectionKey(identity)
        if (!this.selectedKeys.has(key)) return false

        this.selectedKeys.delete(key)
        this.selection = this.selection.length === 1
            ? EMPTY_SELECTION
            : Object.freeze(this.selection.filter((selected) => selectionKey(selected) !== key))
        this.publish([identity])

        return true
    }

    toggle(identity: DiagramSelectionIdentity) {
        return this.isSelected(identity) ? this.remove(identity) : this.add(identity)
    }

    clear() {
        if (this.selection.length === 0) return false

        const removed = this.selection
        this.selection = EMPTY_SELECTION
        this.selectedKeys = new Set<string>()
        this.publish(removed)

        return true
    }

    private handleSessionChange = () => {
        this.clear()
    }

    private handleCollectionMembershipWillChange = (event: Event) => {
        const { memberKind, removedIds } = (event as CustomEvent<DiagramMembershipChangeDetail>).detail
        const removedIdSet = new Set(removedIds)
        const removed = this.selection.filter(({ objectId, objectKind }) => (
            objectKind === memberKind && removedIdSet.has(objectId)
        ))
        if (removed.length === 0) return

        const removedKeys = new Set(removed.map(selectionKey))
        for (const key of removedKeys) this.selectedKeys.delete(key)
        this.selection = this.selection.length === removed.length
            ? EMPTY_SELECTION
            : Object.freeze(this.selection.filter((identity) => !removedKeys.has(selectionKey(identity))))
        this.publish(removed)
    }

    private hasSameMembership(nextKeys: Set<string>) {
        return nextKeys.size === this.selectedKeys.size && [...nextKeys].every((key) => this.selectedKeys.has(key))
    }

    private requireSelectableIdentity(identity: DiagramSelectionIdentity) {
        if (!this.session.getSessionSnapshot()) throw new Error('Cannot select a diagram object without an active edit session')
        if (identity.objectKind === 'edge' && this.session.getEdgeSnapshot(identity.objectId)) return
        if (identity.objectKind === 'group' && this.session.getGroupSnapshot(identity.objectId)) return
        if (identity.objectKind === 'node' && this.session.getNodeSnapshot(identity.objectId)) return

        throw new Error(`Diagram ${identity.objectKind} ${identity.objectId} does not exist`)
    }

    private publish(changedIdentities: readonly DiagramSelectionIdentity[]) {
        for (const identity of changedIdentities) this.dispatchEvent(new Event(selectedChangedEvent(identity)))
        this.dispatchEvent(new Event(SELECTION_MEMBERSHIP_CHANGED_EVENT))
    }

    private subscribe(eventType: string, listener: () => void) {
        this.addEventListener(eventType, listener)

        return () => this.removeEventListener(eventType, listener)
    }
}

export const diagramSelectionService = register('diagramSelectionService', new DiagramSelectionService())

import {
    diagramEditSessionService, type DiagramEditSessionService,
} from '../../services/diagrams/diagram_edit_session_service'
import { diagramGeometryService, type DiagramGeometryService } from '../../services/diagrams/diagram_geometry_service'
import { EditableDiagramActivation } from './editable_diagram_activation'
import { EditableDiagramEdge } from './editable_diagram_edge'
import { EditableDiagramFragment } from './editable_diagram_fragment'
import { EditableDiagramGroup } from './editable_diagram_group'
import { EditableDiagramLifeline } from './editable_diagram_lifeline'
import { EditableDiagramNode } from './editable_diagram_node'
import type { DiagramSelectHandler } from './diagram_selection'
import { useDiagramActivationIds, useDiagramFragmentIds } from './use_diagram_geometry'
import {
    useEditableDiagramEdgeIds, useEditableDiagramGroupIds, useEditableDiagramNodeIds,
} from './use_editable_diagram'

interface CollectionHostProps {
    geometry?: DiagramGeometryService
    session?: DiagramEditSessionService
}

interface SelectableCollectionHostProps extends CollectionHostProps {
    onSelect: DiagramSelectHandler
}

/**
 * Every host below observes one ordered identifier list and nothing else. A field edit inside a member changes no
 * identifier list, so the host is skipped and only the member leaf rerenders.
 */
export function EditableDiagramNodes({
    geometry = diagramGeometryService,
    onSelect,
    session = diagramEditSessionService,
}: SelectableCollectionHostProps) {
    const nodeIds = useEditableDiagramNodeIds(session)

    return nodeIds.map((nodeId) => (
        <EditableDiagramNode geometry={geometry} key={nodeId} nodeId={nodeId} onSelect={onSelect} session={session} />
    ))
}

export function EditableDiagramLifelines({
    geometry = diagramGeometryService,
    session = diagramEditSessionService,
}: CollectionHostProps) {
    const nodeIds = useEditableDiagramNodeIds(session)

    return nodeIds.map((nodeId) => (
        <EditableDiagramLifeline geometry={geometry} key={nodeId} nodeId={nodeId} session={session} />
    ))
}

export function EditableDiagramEdges({
    geometry = diagramGeometryService,
    onSelect,
    session = diagramEditSessionService,
}: SelectableCollectionHostProps) {
    const edgeIds = useEditableDiagramEdgeIds(session)

    return (
        <svg
            aria-label="New diagram connections"
            height="100%"
            style={{ left: 0, overflow: 'visible', position: 'absolute', top: 0, zIndex: 1 }}
            width="100%"
        >
            {edgeIds.map((edgeId) => (
                <EditableDiagramEdge edgeId={edgeId} geometry={geometry} key={edgeId} onSelect={onSelect} session={session} />
            ))}
        </svg>
    )
}

export function EditableDiagramGroups({
    geometry = diagramGeometryService,
    session = diagramEditSessionService,
}: CollectionHostProps) {
    const groupIds = useEditableDiagramGroupIds(session)

    return groupIds.map((groupId) => (
        <EditableDiagramGroup geometry={geometry} groupId={groupId} key={groupId} session={session} />
    ))
}

export function EditableDiagramFragments({
    geometry = diagramGeometryService,
    session = diagramEditSessionService,
}: CollectionHostProps) {
    const fragmentIds = useDiagramFragmentIds(geometry)

    return fragmentIds.map((fragmentId) => (
        <EditableDiagramFragment fragmentId={fragmentId} geometry={geometry} key={fragmentId} session={session} />
    ))
}

export function EditableDiagramActivations({ geometry = diagramGeometryService }: CollectionHostProps) {
    const activationIds = useDiagramActivationIds(geometry)

    return activationIds.map((activationId) => (
        <EditableDiagramActivation activationId={activationId} geometry={geometry} key={activationId} />
    ))
}

import { memo } from 'react'
import { diagramGeometryService, type DiagramGeometryService } from '../../services/diagrams/diagram_geometry_service'
import { SequenceActivation } from './sequence_activation'
import { useDiagramActivationField } from './use_diagram_geometry'

interface EditableDiagramActivationProps {
    activationId: string
    geometry?: DiagramGeometryService
}

/** One activation bar of the New diagram; activations exist only as derived geometry. */
function EditableDiagramActivationLeaf({
    activationId,
    geometry = diagramGeometryService,
}: EditableDiagramActivationProps) {
    const height = useDiagramActivationField(activationId, 'height', geometry)
    const width = useDiagramActivationField(activationId, 'width', geometry)
    const x = useDiagramActivationField(activationId, 'x', geometry)
    const y = useDiagramActivationField(activationId, 'y', geometry)
    if (height === null || width === null) return null

    return <SequenceActivation activation={{ height, id: activationId, width, x: x ?? 0, y: y ?? 0 }} />
}

/** Memoised so a collection host rerender caused by another member cannot rerender this leaf. */
export const EditableDiagramActivation = memo(EditableDiagramActivationLeaf)

import { memo } from 'react'
import type { DiagramWaypoint } from '../../services/diagrams/diagram_data'
import {
    diagramEditSessionService, type DiagramEditSessionService,
} from '../../services/diagrams/diagram_edit_session_service'
import { diagramGeometryService, type DiagramGeometryService } from '../../services/diagrams/diagram_geometry_service'
import type { PositionedDiagramEdge } from '../../services/diagrams/diagram_layout'
import { DiagramEdge } from './diagram_edge'
import type { DiagramSelectHandler } from './diagram_selection'
import { useDiagramEdgeLabelPlacement, useDiagramEdgeRoute } from './use_diagram_geometry'
import { useEditableDiagramEdgeField } from './use_editable_diagram'

const EMPTY_NODE_LABELS: ReadonlyMap<string, string> = new Map()

interface EditableDiagramEdgeProps {
    edgeId: string
    geometry?: DiagramGeometryService
    onSelect: DiagramSelectHandler
    session?: DiagramEditSessionService
}

/**
 * One connection of the New diagram. It observes its own model fields and its own derived route.
 */
function EditableDiagramEdgeLeaf({
    edgeId,
    geometry = diagramGeometryService,
    onSelect,
    session = diagramEditSessionService,
}: EditableDiagramEdgeProps) {
    const from = useEditableDiagramEdgeField(edgeId, 'from', session)
    const fromCardinality = useEditableDiagramEdgeField(edgeId, 'fromCardinality', session)
    const kind = useEditableDiagramEdgeField(edgeId, 'kind', session)
    const label = useEditableDiagramEdgeField(edgeId, 'label', session)
    const to = useEditableDiagramEdgeField(edgeId, 'to', session)
    const toCardinality = useEditableDiagramEdgeField(edgeId, 'toCardinality', session)
    const labelPlacement = useDiagramEdgeLabelPlacement(edgeId, geometry)
    const points = useDiagramEdgeRoute(edgeId, geometry)
    if (from === null || to === null || kind === null || points.length === 0) return null

    const edge: PositionedDiagramEdge = {
        from,
        id: edgeId,
        kind,
        points: points as DiagramWaypoint[],
        to,
        ...(fromCardinality ? { fromCardinality } : {}),
        ...(label ? { label } : {}),
        ...(labelPlacement ? { labelPlacement } : {}),
        ...(toCardinality ? { toCardinality } : {}),
    }

    return <DiagramEdge edge={edge} nodeLabels={EMPTY_NODE_LABELS} onSelect={onSelect} />
}

/** Memoised so a collection host rerender caused by another member cannot rerender this leaf. */
export const EditableDiagramEdge = memo(EditableDiagramEdgeLeaf)

import { memo } from 'react'
import {
    diagramEditSessionService, type DiagramEditSessionService,
} from '../../services/diagrams/diagram_edit_session_service'
import { diagramGeometryService, type DiagramGeometryService } from '../../services/diagrams/diagram_geometry_service'
import type { PositionedDiagramGroup } from '../../services/diagrams/diagram_layout'
import { DiagramGroup } from './diagram_group'
import { useDiagramGroupGeometryField } from './use_diagram_geometry'
import { useEditableDiagramGroupField } from './use_editable_diagram'

interface EditableDiagramGroupProps {
    geometry?: DiagramGeometryService
    groupId: string
    session?: DiagramEditSessionService
}

/** One containment box of the New diagram, bound to its own label and its own derived box. */
function EditableDiagramGroupLeaf({
    geometry = diagramGeometryService,
    groupId,
    session = diagramEditSessionService,
}: EditableDiagramGroupProps) {
    const label = useEditableDiagramGroupField(groupId, 'label', session)
    const height = useDiagramGroupGeometryField(groupId, 'height', geometry)
    const width = useDiagramGroupGeometryField(groupId, 'width', geometry)
    const x = useDiagramGroupGeometryField(groupId, 'x', geometry)
    const y = useDiagramGroupGeometryField(groupId, 'y', geometry)
    if (label === null || height === null || width === null) return null

    // Membership is edited elsewhere and is not rendered by the box, so this view object carries no member IDs.
    const group: PositionedDiagramGroup = { height, id: groupId, label, nodeIds: [], width, x: x ?? 0, y: y ?? 0 }

    return <DiagramGroup group={group} />
}

/** Memoised so a collection host rerender caused by another member cannot rerender this leaf. */
export const EditableDiagramGroup = memo(EditableDiagramGroupLeaf)

import { memo } from 'react'
import {
    diagramEditSessionService, type DiagramEditSessionService,
} from '../../services/diagrams/diagram_edit_session_service'
import { diagramGeometryService, type DiagramGeometryService } from '../../services/diagrams/diagram_geometry_service'
import type { PositionedSequenceFragment } from '../../services/diagrams/diagram_layout'
import { SequenceFragment } from './sequence_fragment'
import { useDiagramFragmentGeometryField } from './use_diagram_geometry'
import { useEditableDiagramFragmentField } from './use_editable_diagram'

interface EditableDiagramFragmentProps {
    fragmentId: string
    geometry?: DiagramGeometryService
    session?: DiagramEditSessionService
}

/** One sequence frame of the New diagram, bound to its own operator, box, divider, and guard positions. */
function EditableDiagramFragmentLeaf({
    fragmentId,
    geometry = diagramGeometryService,
    session = diagramEditSessionService,
}: EditableDiagramFragmentProps) {
    const operator = useEditableDiagramFragmentField(fragmentId, 'operator', session)
    const dividerY = useDiagramFragmentGeometryField(fragmentId, 'dividerY', geometry)
    const guardPositions = useDiagramFragmentGeometryField(fragmentId, 'guardPositions', geometry)
    const height = useDiagramFragmentGeometryField(fragmentId, 'height', geometry)
    const width = useDiagramFragmentGeometryField(fragmentId, 'width', geometry)
    const x = useDiagramFragmentGeometryField(fragmentId, 'x', geometry)
    const y = useDiagramFragmentGeometryField(fragmentId, 'y', geometry)
    if (!operator || typeof height !== 'number' || typeof width !== 'number') return null

    const fragment: PositionedSequenceFragment = {
        guardPositions: Array.isArray(guardPositions) ? [...guardPositions] : [],
        height,
        id: fragmentId,
        operator,
        width,
        x: typeof x === 'number' ? x : 0,
        y: typeof y === 'number' ? y : 0,
        ...(typeof dividerY === 'number' ? { dividerY } : {}),
    }

    return <SequenceFragment fragment={fragment} />
}

/** Memoised so a collection host rerender caused by another member cannot rerender this leaf. */
export const EditableDiagramFragment = memo(EditableDiagramFragmentLeaf)

import { Profiler, type ReactNode } from 'react'
import { act, cleanup, render, screen } from '@testing-library/react'
import { afterEach, describe, expect, it } from 'vitest'
import type { DiagramData } from '../../services/diagrams/diagram_data'
import { DiagramEditSessionService } from '../../services/diagrams/diagram_edit_session_service'
import { DiagramGeometryService } from '../../services/diagrams/diagram_geometry_service'
import type { DiagramRecord } from '../../services/diagrams/diagram_index'
import type { DiagramViewSourceSnapshot } from '../../services/diagrams/diagram_view_service'
import { EditableDiagram, EditableDiagramSurface } from './editable_diagram'
import { EditableDiagramNodes } from './editable_diagram_collections'
import { EditableDiagramNode } from './editable_diagram_node'

const diagram: DiagramData = {
    edges: [{ from: 'orders', id: 'orders-store', kind: 'connection', label: 'writes', to: 'store' }],
    groups: [{ id: 'backend', label: 'Backend', nodeIds: ['orders', 'store'] }],
    meta: { description: 'Orders architecture', title: 'Overview', type: 'architecture', version: 1 },
    nodes: [
        { id: 'orders', label: 'Orders', role: 'focal' },
        { id: 'store', label: 'Store', role: 'store' },
    ],
}
const record: DiagramRecord = { actionId: 'overview', id: 'diagram-1', label: 'Overview', path: 'design/diagrams/overview.json' }
const project = { branch: 'main', id: 'project', rootPath: 'C:/repo' }

class DiagramSourceStub extends EventTarget {
    private readonly source: DiagramViewSourceSnapshot = { diagram, record }

    getSourceSnapshot = () => this.source

    subscribeSource = (listener: () => void) => {
        this.addEventListener('sourceChanged', listener)

        return () => this.removeEventListener('sourceChanged', listener)
    }
}

type RenderCounts = Map<string, number>

function Counted({ children, counts, id }: { children: ReactNode, counts: RenderCounts, id: string }) {
    const handleRender = () => counts.set(id, (counts.get(id) ?? 0) + 1)

    return <Profiler id={id} onRender={handleRender}>{children}</Profiler>
}

function createHarness() {
    const session = new DiagramEditSessionService(new DiagramSourceStub())
    session.bindProject(project)
    session.start()
    const geometry = new DiagramGeometryService(session)

    return { geometry, session }
}

/** Counts commits of one node leaf; the surrounding host is measured through its identifier snapshot instead. */
function MeasuredNodes({ counts, geometry, session }: {
    counts: RenderCounts,
    geometry: DiagramGeometryService,
    session: DiagramEditSessionService,
}) {
    return (
        <>
            <EditableDiagramNodes geometry={geometry} onSelect={() => undefined} session={session} />
            <Counted counts={counts} id="orders">
                <EditableDiagramNode geometry={geometry} nodeId="orders" onSelect={() => undefined} session={session} />
            </Counted>
        </>
    )
}

afterEach(cleanup)

describe('editable diagram', () => {
    it('renders metadata, surface, and every collection from service data alone', () => {
        const { geometry, session } = createHarness()
        render(<EditableDiagram geometry={geometry} session={session} />)

        expect(screen.getByText('Overview')).toBeTruthy()
        expect(screen.getByText('Orders architecture')).toBeTruthy()
        expect(screen.getByLabelText('New diagram')).toBeTruthy()
        expect(screen.getByRole('button', { name: 'Orders' })).toBeTruthy()
        expect(screen.getByRole('button', { name: 'Store' })).toBeTruthy()
        expect(screen.getByRole('button', { name: 'writes' })).toBeTruthy()
        expect(screen.getByRole('group', { name: 'Backend' })).toBeTruthy()
    })

    it('shows an accepted edit in the New diagram immediately', () => {
        const { geometry, session } = createHarness()
        render(<EditableDiagram geometry={geometry} session={session} />)

        act(() => { session.setNodeField('store', 'label', 'Order store') })

        expect(screen.getByRole('button', { name: 'Order store' })).toBeTruthy()
        expect(screen.queryByRole('button', { name: 'Store' })).toBeNull()
    })

    it('leaves the node collection host untouched when one node field changes', () => {
        const { geometry, session } = createHarness()
        const counts: RenderCounts = new Map()
        render(<MeasuredNodes counts={counts} geometry={geometry} session={session} />)
        const before = new Map(counts)
        const nodeIds = session.getNodeIdsSnapshot()

        act(() => { session.setNodeField('orders', 'label', 'Order intake') })

        expect(counts.get('orders')).toBeGreaterThan(before.get('orders') ?? 0)
        // The host observes this snapshot only, so an unchanged reference is exactly a skipped host render.
        expect(session.getNodeIdsSnapshot()).toBe(nodeIds)
    })

    it('rerenders the node collection host and adds one leaf when a node is added', () => {
        const { geometry, session } = createHarness()
        const counts: RenderCounts = new Map()
        render(<MeasuredNodes counts={counts} geometry={geometry} session={session} />)
        const before = new Map(counts)
        const nodeIds = session.getNodeIdsSnapshot()

        act(() => { session.createNode({ label: 'Mail', role: 'external' }) })

        expect(session.getNodeIdsSnapshot()).not.toBe(nodeIds)
        expect(screen.getByRole('button', { name: 'Mail' })).toBeTruthy()
        // The added member creates one leaf; the existing leaf is reused rather than rerendered.
        expect(counts.get('orders')).toBe(before.get('orders'))
    })

    it('resizes the surface without rerendering the collection hosts inside it', () => {
        const { geometry, session } = createHarness()
        const counts: RenderCounts = new Map()
        render(
            <EditableDiagramSurface geometry={geometry}>
                <Counted counts={counts} id="host"><div data-testid="surface-child" /></Counted>
            </EditableDiagramSurface>,
        )
        const before = new Map(counts)

        act(() => { session.setNodeField('store', 'x', 2000) })

        expect(geometry.getSurfaceFieldSnapshot('width')).toBeGreaterThan(2000)
        expect(counts.get('host')).toBe(before.get('host'))
    })
})

